using System.IO;using System.Net;using System.Net.Http;using System.Text.Json;using ShareLink.BrowserSharing;
namespace ShareLink.BrowserShareProbe;
internal static class SessionRestartChecks {
 public static async Task RunAsync(string output){Directory.CreateDirectory(output);var checks=new List<object>();void Check(string n,bool ok){if(!ok)throw new Exception(n);checks.Add(new{name=n,passed=ok});}
 string first=Path.Combine(output,"session-one.txt"),next=Path.Combine(output,"session-two.txt"),received=Path.Combine(output,"owned-receive");File.WriteAllText(first,"old dedicated fixture");File.WriteAllText(next,"new dedicated fixture");Directory.CreateDirectory(received);
 async Task<string?> Token(HttpClient c){using var d=JsonDocument.Parse(await c.GetStringAsync("manifest.json"));return d.RootElement.GetProperty("uploadToken").GetString();}
 async Task<HttpResponseMessage> Post(HttpClient c,string token,string name){using var r=new HttpRequestMessage(HttpMethod.Post,"upload"){Content=new ByteArrayContent(new byte[]{1,2,3})};r.Headers.Add("X-ShareLink-Upload",token);r.Headers.Add("X-ShareLink-Filename",name);return await c.SendAsync(r);}
 Directory.CreateDirectory(Path.Combine(output,"one"));Directory.CreateDirectory(Path.Combine(output,"two"));int port;string oldId,oldToken;
 await using(var server=new BrowserFileServer([first],Path.Combine(output,"one"),true)){await server.StartAsync(IPAddress.Loopback,0,CancellationToken.None);port=server.Port;oldId=server.Files[0].Id;server.EnableUploads(received);using var c=new HttpClient(new HttpClientHandler{UseProxy=false}){BaseAddress=new Uri($"http://127.0.0.1:{port}/")};c.DefaultRequestHeaders.Add("X-ShareLink-Session",server.SessionId);oldToken=(await Token(c))!;Check("first selected file reachable",(await c.GetAsync("files/"+oldId)).IsSuccessStatusCode);}
 await using(var server=new BrowserFileServer([next],Path.Combine(output,"two"),true)){await server.StartAsync(IPAddress.Loopback,port,CancellationToken.None);using var c=new HttpClient(new HttpClientHandler{UseProxy=false}){BaseAddress=new Uri($"http://127.0.0.1:{port}/")};c.DefaultRequestHeaders.Add("X-ShareLink-Session",server.SessionId);Check("same interface and port reused",server.Port==port);Check("new session starts without upload consent",await Token(c)==null);using(var stale=await c.GetAsync("files/"+oldId))Check("old file URL rejected on new session",stale.StatusCode==HttpStatusCode.NotFound);string m=await c.GetStringAsync("manifest.json");Check("new manifest contains only new selected file",m.Contains("session-two.txt")&&!m.Contains("session-one.txt"));server.EnableUploads(received);string token=(await Token(c))!;Check("upload token rotates across sessions",token!=oldToken);using(var stale=await Post(c,oldToken,"stale.bin"))Check("old token remains rejected after new consent",stale.StatusCode==HttpStatusCode.Forbidden&&!File.Exists(Path.Combine(received,"stale.bin")));
 if(!Path.GetFullPath(received).StartsWith(Path.GetFullPath(output)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||Directory.EnumerateFileSystemEntries(received).Any())throw new Exception("Owned empty directory guard failed");Directory.Delete(received,false);
 using(var failed=await Post(c,token,"save-failure.bin"))Check("missing owned receive directory reports save failure",failed.StatusCode==(HttpStatusCode)507);var failedRow=server.Progress.Snapshot().SelectMany(r=>r.Files).Single(f=>f.Name=="save-failure.bin");Check("failed save never shown as completed",failedRow.Interrupted&&!failedRow.Complete&&failedRow.Active==0);Directory.CreateDirectory(received);using(var retry=await Post(c,token,"save-retry.bin"))Check("retry succeeds after owned directory restored",retry.IsSuccessStatusCode);Check("retry original exact bytes",File.ReadAllBytes(Path.Combine(received,"save-retry.bin")).SequenceEqual(new byte[]{1,2,3}));Check("both selected sources preserved",File.Exists(first)&&File.Exists(next));}
 File.WriteAllText(Path.Combine(output,"session-restart-checks.json"),JsonSerializer.Serialize(new{passed=true,scope="actual Windows HTTP on same loopback IP and port, stale file URL/token and safe receive IO failure; not old-page automatic refresh or physical same-network acceptance",checks},new JsonSerializerOptions{WriteIndented=true}));
 }
}
